with valid_employees as (select *, if(is_remote, 'Yes', 'No') as is_remote_label from employees where not is_remote or manager_id is null), hire_quarter_summary as (select quarter(hire_date) as hire_quarter, sum(case when job_title = 'Director' then 1 else 0 end) as director_count, count(case when level = 'L2' then 1 end) as l2_count from valid_employees group by quarter(hire_date)) select hire_quarter, director_count, l2_count from hire_quarter_summary where l2_count < 6
